import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry tall_skinny_matmul(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 K
)
{
    .reg .u64 %rd<20>;
    .reg .u32 %r<20>;
    .reg .f32 %f<20>;
    .reg .pred %p<8>;

    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1, [M];
    ld.param.u32 %r2, [K];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;

    mov.u32 %r3, %ctaid.x;
    mov.u32 %r4, %ntid.x;
    mov.u32 %r5, %tid.x;
    mad.lo.u32 %r6, %r3, %r4, %r5;   // col

    mov.u32 %r7, %ctaid.y;
    mov.u32 %r8, %ntid.y;
    mov.u32 %r9, %tid.y;
    mad.lo.u32 %r10, %r7, %r8, %r9;  // row

    setp.ge.u32 %p1, %r6, %r1;
    setp.ge.u32 %p2, %r10, %r1;
    or.pred %p3, %p1, %p2;
    @%p3 bra DONE;

    // A row base pointer: A + row*K*4
    mul.lo.u32 %r11, %r10, %r2;
    mul.wide.u32 %rd4, %r11, 4;
    add.s64 %rd5, %rd1, %rd4;

    mov.f32 %f1, 0f00000000;
    mov.u32 %r12, 0;

LOOP:
    setp.ge.u32 %p4, %r12, %r2;
    @%p4 bra LOOP_END;

    // A[row,k]
    mul.wide.u32 %rd6, %r12, 4;
    add.s64 %rd7, %rd5, %rd6;
    ld.global.f32 %f2, [%rd7];

    // B[k,col] = B + (k*M+col)*4
    mul.lo.u32 %r13, %r12, %r1;
    add.u32 %r14, %r13, %r6;
    mul.wide.u32 %rd8, %r14, 4;
    add.s64 %rd9, %rd2, %rd8;
    ld.global.f32 %f3, [%rd9];

    fma.rn.f32 %f1, %f2, %f3, %f1;

    add.u32 %r12, %r12, 1;
    bra LOOP;

LOOP_END:
    // C[row,col] = C + (row*M+col)*4
    mul.lo.u32 %r15, %r10, %r1;
    add.u32 %r16, %r15, %r6;
    mul.wide.u32 %rd10, %r16, 4;
    add.s64 %rd11, %rd3, %rd10;
    st.global.f32 [%rd11], %f1;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("tall_skinny_matmul")

class ModelNew(nn.Module):
    """
    Simple model that performs a single matrix multiplication (C = A * B)
    where one of the matrices is tall and skinny, implemented via a custom
    PTX kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A, B):
        assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32
        assert A.is_contiguous() and B.is_contiguous()

        M, K = A.shape
        K2, M2 = B.shape
        assert K == K2 and M == M2, "Shape mismatch for tall-skinny matmul"

        C = torch.empty((M, M), dtype=torch.float32, device=A.device)

        module = _get_ptx_module()

        block_x, block_y = 16, 16
        grid_x = (M + block_x - 1) // block_x
        grid_y = (M + block_y - 1) // block_y

        module.launch(
            "tall_skinny_matmul",
            grid=(grid_x, grid_y, 1),
            block=(block_x, block_y, 1),
            arguments=[A, B, C, u32(M), u32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )

        return C

